    "shortDescription": "Надійний подрібнювач бадилля Struik GLUTTON (Struik) для чистого зрізу і мульчування вегетативної маси картоплі перед копанням.",
    "fullDescription": "Професійний польовий агрегат Struik GLUTTON подрібнювач бадилля від європейського лідера Struik створений для якісної підготовки картопляного поля до збирання врожаю. Високошвидкісний динамічно збалансований ротор зі спеціальними загартованими ножами та вакуумними дефлекторами акуратно піднімає навіть полеглу гичку з борозни та подрібнює її на дрібну мульчу. Своєчасне скошування бадилля прискорює дозрівання бульб, сприяє зміцненню шкірки картоплі, захищає врожай від ураження фітофторозом та істотно полегшує подальшу роботу комбайна. AGRORENTEX пропонує перевірену техніку з офіційною гарантією, сервісною діагностикою та оперативною доставкою в господарство.",
