    "fullDescription": "Польовий агрегат Struik WEED-MASTER машина для механічного видалення бур'янів розроблений для глибокого структурного розпушування ґрунту, активного формування об'ємних трапецієподібних гребенів та міжрядного догляду за овочевими культурами. Завдяки оптимізованій геометрії ножів і робочих дисків агрегат створює дрібногрудкувату структуру без ущільнення підошви, зберігаючи капілярну вологу. Сформовані гребені відмінно зберігають цілісність до збирання, захищаючи коренеплоди від прямого сонця та позеленіння. Сервісна служба AGRORENTEX здійснює підключення, налаштування робочих параметрів та повний технічний супровід.",
